"use strict";
async function portalRequest(action,body){const response=await fetch('/api/portal/'+action,{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'The portal is unavailable.');return data;}
(async()=>{try{const session=await portalRequest('session');window.isGameAdmin=session.user?.role==='admin';if(window.isGameAdmin&&['/game','/game/','/index.html'].includes(location.pathname)&&/^#admin(Round|Planets|Ships|State)$/.test(location.hash)&&typeof navigate==='function')navigate(location.hash.slice(1));document.querySelectorAll('[data-profile-link],[data-session-link]').forEach(el=>el.hidden=!session.user);document.querySelectorAll('[data-staff-link]').forEach(el=>el.hidden=session.user?.role!=='admin');document.querySelectorAll('[data-register-link]').forEach(el=>el.hidden=!!session.user);initializePortalControls(session);const label=document.getElementById('portalUser');if(label)label.textContent=session.user?'Signed in as '+session.user.username:'Commander portal';const login=document.getElementById('portalLoginLink');if(login&&session.user){login.textContent='Continue game';login.href='/game';}const form=document.getElementById('loginForm');if(form){if(session.user){location.replace('/game');return;}const setup=session.setupRequired;document.getElementById('loginHeading').textContent=setup?'Create the administrator':'Welcome back';document.getElementById('loginIntro').textContent=setup?'Set up the initial admin account for this game portal.':'Sign in with your game account to enter Starfall Command.';document.getElementById('loginSubmit').textContent=setup?'Create admin account':'Sign in';if(setup){form.elements.username.value='admin';form.elements.username.readOnly=true;}form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('loginSubmit'),status=document.getElementById('loginStatus');button.disabled=true;status.textContent='';try{await portalRequest(setup?'setup':'login',{username:form.elements.username.value,password:form.elements.password.value});form.elements.password.value='';location.replace('/game');}catch(error){status.textContent=error.message;button.disabled=false;}});}}catch(error){const status=document.getElementById('loginStatus');if(status)status.textContent=error.message;}})();
const manualSearch=document.getElementById('manualSearch');if(manualSearch)manualSearch.addEventListener('input',()=>{const query=manualSearch.value.trim().toLowerCase();let visible=0;document.querySelectorAll('.manual-section').forEach(section=>{section.hidden=!!query&&!section.textContent.toLowerCase().includes(query);if(!section.hidden)visible++;});document.getElementById('manualSearchStatus').textContent=visible+' categories';});
document.addEventListener('click',async event=>{if(event.target.closest('[data-portal-logout]')){try{await portalRequest('logout',{});location.href='/';}catch(error){alert(error.message);}}});

function applyPortalSkin(skin){if(!['Neutral','Terran','Cathaar','Xandathrii','Zikonian','Eitraides'].includes(skin))skin='Neutral';document.body.dataset.portalSkin=skin;const picker=document.getElementById('portalTheme');if(picker)picker.value=skin;try{localStorage.setItem('starfall-portal-skin',skin);}catch{}}
if(document.getElementById('portalTheme')){let skin='Neutral';try{skin=localStorage.getItem('starfall-portal-skin')||skin;}catch{}applyPortalSkin(skin);}
document.addEventListener('change',event=>{if(event.target.id==='portalTheme')applyPortalSkin(event.target.value);if(event.target.id==='manualShipRace'){const race=event.target.value;document.querySelectorAll('[data-ship-race]').forEach(card=>card.hidden=race!=='all'&&card.dataset.shipRace!==race);}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-preview-race]');if(button)applyPortalSkin(button.dataset.previewRace);});

document.addEventListener('change',event=>{if(event.target.id==='manualStatsRace')document.querySelectorAll('[data-stat-race]').forEach(table=>table.hidden=event.target.value!=='all'&&table.dataset.statRace!==event.target.value);});

async function initializePortalControls(session){const register=document.getElementById('registerForm');if(register){if(session.user){location.replace('/profile.html');return;}register.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('registerStatus');if(register.elements.password.value!==register.elements.confirmPassword.value){status.textContent='Passwords do not match.';return;}const button=register.querySelector('button');button.disabled=true;try{await portalRequest('register',{username:register.elements.username.value,password:register.elements.password.value});register.reset();location.replace('/profile.html');}catch(error){status.textContent=error.message;button.disabled=false;}});}const profile=document.getElementById('profileForm');if(profile){try{const data=await portalRequest('profile');document.getElementById('profileIdentity').textContent='Account: '+data.user.username+' · '+data.user.role;document.getElementById('profilePlanet').textContent=data.planet?'Planet: '+data.planet.name+' · '+data.planet.coords:'No planet assigned. Contact game staff.';profile.elements.displayName.value=data.planet?.username||data.profile.display_name||data.user.username;profile.elements.theme.value=data.profile.theme;profile.addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('profile',{displayName:profile.elements.displayName.value,theme:profile.elements.theme.value});applyPortalSkin(profile.elements.theme.value);document.getElementById('profileStatus').textContent='Profile saved.';}catch(error){document.getElementById('profileStatus').textContent=error.message;}});}catch(error){document.getElementById('profileStatus').textContent=error.message;}}if(document.getElementById('staffUsers')){try{const data=await portalRequest('staff'),table=document.createElement('table');table.className='table';const head=document.createElement('tr');for(const label of ['Account','Role','Planet','Assign']){const cell=document.createElement('th');cell.textContent=label;head.append(cell);}table.append(head);for(const user of data.users){const row=document.createElement('tr'),name=document.createElement('td'),role=document.createElement('td'),owned=document.createElement('td'),action=document.createElement('td'),select=document.createElement('select'),button=document.createElement('button');name.textContent=user.username;role.textContent=user.role;owned.textContent=data.planets.filter(p=>p.ownerId===user.id).map(p=>p.name+' · '+p.coords).join(', ')||'Unassigned';for(const p of data.planets.filter(p=>!p.ownerId||p.ownerId===user.id)){const option=document.createElement('option');option.value=p.id;option.textContent=p.name+' · '+p.coords;option.selected=p.ownerId===user.id;select.append(option);}button.textContent='ASSIGN PLANET';button.className='button';button.disabled=!select.options.length;button.addEventListener('click',async()=>{try{await portalRequest('staff-assign',{userId:user.id,planetId:select.value});location.reload();}catch(error){document.getElementById('staffStatus').textContent=error.message;}});action.append(select,button);row.append(name,role,owned,action);table.append(row);}document.getElementById('staffUsers').replaceChildren(table);}catch(error){document.getElementById('staffStatus').textContent=error.message;}document.getElementById('staffResetForm').addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('reset',{confirmation:e.target.elements.confirmation.value});localStorage.removeItem('starfall-round-v2');localStorage.removeItem('starfall-state');document.getElementById('staffResetStatus').textContent='Round reset. Default planets regenerated.';}catch(error){document.getElementById('staffResetStatus').textContent=error.message;}});}}

const ARTICLE_ICON_PATHS={'Game mechanic update':'<path d="M32 10v44M10 32h44M16 16l32 32M16 48l32-32"/><circle cx="32" cy="32" r="12"/>','Round update':'<circle cx="32" cy="32" r="23"/><path d="M32 15v18l12 8"/>','Stats update':'<path d="M12 52V35h10v17M27 52V23h10v29M42 52V12h10v40"/>','Error update':'<path d="m32 8 26 46H6zM32 24v14m0 7v2"/>','Pauzed and resumed update':'<path d="M10 15h8v34h-8zM24 15h8v34h-8zM40 15l19 17-19 17z"/>'};
function articleIcon(category){return '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round" aria-hidden="true">'+(ARTICLE_ICON_PATHS[category]||ARTICLE_ICON_PATHS['Round update'])+'</svg>';}
function articleText(tag,value){const node=document.createElement(tag);node.textContent=value;return node;}
(async()=>{const form=document.getElementById('staffArticleForm');if(form){const cat=document.getElementById('articleCategory'),preview=document.getElementById('articleCategoryIcon');const refresh=()=>{preview.innerHTML=articleIcon(cat.value);preview.setAttribute('aria-label',cat.value);};refresh();cat.addEventListener('change',refresh);form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('staffArticleSubmit'),status=document.getElementById('staffArticleStatus');button.disabled=true;try{const result=await portalRequest('articles',{id:form.elements.namedItem('articleId').value||undefined,title:form.elements.namedItem('title').value,synopsis:form.elements.namedItem('synopsis').value,category:form.elements.namedItem('category').value,body:form.elements.namedItem('body').value});form.reset();document.getElementById('staffArticleSubmit').textContent='PUBLISH ARTICLE';refresh();loadStaffArticles();status.replaceChildren(articleText('span','Published. '));const link=articleText('a','Open article →');link.href='/news-article.html?id='+encodeURIComponent(result.id);status.append(link);}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});}const cards=document.getElementById('staffNewsCards');if(cards){try{const data=await portalRequest('articles');for(const a of data.articles.slice(0,location.pathname==='/news.html'?100:3)){const card=document.createElement('article');card.className='card';const icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);const meta=articleText('span',new Date(a.published_at).toLocaleDateString()+' · '+a.category);meta.className='eyebrow';const link=articleText('a','Read news article →');link.href='/news-article.html?id='+encodeURIComponent(a.id);card.append(icon,meta,articleText('h2',a.title),articleText('p',a.synopsis),link);cards.append(card);}document.getElementById('staffPublishedNews').hidden=!data.articles.length;}catch{cards.textContent='Staff dispatches are temporarily unavailable.';}}const view=document.getElementById('staffArticleView');if(view){try{const id=new URLSearchParams(location.search).get('id');if(!id)throw Error('Select an article from the news archive.');const data=await portalRequest('articles?id='+encodeURIComponent(id)),a=data.article,icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);view.replaceChildren(icon,articleText('span',a.category+' · '+new Date(a.published_at).toLocaleString()),articleText('h1',a.title),articleText('p',a.synopsis));for(const paragraph of a.body.split(/\n\s*\n/)){const p=document.createElement('p');p.style.whiteSpace='pre-wrap';renderArticleFormatting(p,paragraph);view.append(p);}document.title=a.title+' · Starfall Command';}catch(error){view.textContent=error.message;}}})();

function renderArticleFormatting(parent,text){const pattern=/\[(b|i|font=(?:sans-serif|serif|monospace)|size=(?:14|18|24|32))\]([\s\S]*?)\[\/(b|i|font|size)\]/g;let start=0,match;while((match=pattern.exec(text))){parent.append(document.createTextNode(text.slice(start,match.index)));const kind=match[1].split('=')[0];if(kind!==match[3]){parent.append(document.createTextNode(match[0]));}else{const el=document.createElement(kind==='b'?'strong':kind==='i'?'em':'span');if(kind==='font')el.style.fontFamily=match[1].split('=')[1];if(kind==='size')el.style.fontSize=match[1].split('=')[1]+'px';renderArticleFormatting(el,match[2]);parent.append(el);}start=pattern.lastIndex;}parent.append(document.createTextNode(text.slice(start)));}
function formatArticleSelection(tag){const editor=document.getElementById('articleBodyEditor');if(!editor)return;const from=editor.selectionStart,to=editor.selectionEnd,selected=editor.value.slice(from,to)||'Your text',close=tag.split('=')[0],wrapped='['+tag+']'+selected+'[/'+close+']';editor.setRangeText(wrapped,from,to,'select');editor.focus();}
document.addEventListener('click',e=>{const button=e.target.closest('[data-article-format]');if(button)formatArticleSelection(button.dataset.articleFormat);});document.addEventListener('change',e=>{if(e.target.matches('[data-article-font]'))formatArticleSelection('font='+e.target.value);if(e.target.matches('[data-article-size]'))formatArticleSelection('size='+e.target.value);});

async function loadStaffArticles(){const list=document.getElementById('staffArticlesList');if(!list)return;try{const data=await portalRequest('articles');list.replaceChildren();if(!data.articles.length)list.append(articleText('p','No staff articles published yet.'));for(const a of data.articles){const card=document.createElement('article');card.className='staff-article-row';const icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);const title=articleText('h3',a.title),meta=articleText('p',a.category+' · '+new Date(a.published_at).toLocaleString()),button=articleText('button','EDIT');button.type='button';button.className='button';button.addEventListener('click',async()=>{try{const {article}=await portalRequest('articles?id='+encodeURIComponent(a.id)),form=document.getElementById('staffArticleForm');for(const key of ['title','synopsis','category','body'])form.elements.namedItem(key).value=article[key];form.elements.namedItem('articleId').value=article.id;document.getElementById('staffArticleSubmit').textContent='SAVE CHANGES';document.getElementById('articleCategoryIcon').innerHTML=articleIcon(article.category);document.getElementById('staffArticleStatus').textContent='Editing '+article.title;form.scrollIntoView({behavior:'smooth',block:'start'});}catch(error){list.append(articleText('p',error.message));}});const copy=document.createElement('div');copy.append(title,meta);card.append(icon,copy,button);list.append(card);}}catch(error){list.textContent=error.message;}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-staff-tab]');if(tab){document.querySelectorAll('[data-staff-section]').forEach(section=>section.hidden=section.dataset.staffSection!==tab.dataset.staffTab);document.querySelectorAll('[data-staff-tab]').forEach(button=>button.classList.toggle('active',button===tab));}if(e.target.id==='staffNewArticle'){document.getElementById('staffArticleForm').reset();document.getElementById('staffArticleSubmit').textContent='PUBLISH ARTICLE';document.getElementById('staffArticleStatus').textContent='New article';}});loadStaffArticles();
